namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// The death loop (M3 3.2 lane da), read by the headless host's death-and-regear scenario and the game's bsd-death leg; parsed by
    /// src/Lifestone.Client/Session/Scenarios/DeathOptions.cs (<c>DeathOptions.FromArguments</c>).
    /// </summary>
    public static OptionGroup Death() => new("Death loop", "main scene and headless host",
    [
        new("--death-seconds", "S", "The most session-clock seconds the death loop waits among the Black Spawn Den's tuskers for them to kill the unbuffed mage (1 to 3600, default 600), counted from the start of the wait (after the gear, the bind at Holtburg's lifestone and the suicide that unbuffs); past it the scenario fails loudly with the hits, evades and the lowest health share. A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-stages", "LIST", "Which stages of the death-and-regear scenario run (headless host only; the game's bsd-death leg always runs all): a list of gear, bind, den, unbuff, death, corpse, regear, rebuff, fight, vitae, joined by commas or plus signs, or all (the default) or none. vitae is the last stage (D37): after the verdict's measures are frozen and before the log off, BSD Mage's vitae is paid back with the server mod's xp verb (the experience ACE's rule asks, refused if it would cross the next level) and the line reports vitae_paid= and vitae_after=. A run without the death stage judges nothing about the death, so --scenario=death-and-regear --death-stages=vitae pays the vitae alone. A bad value is an error."),
        new("--death-recover-corpse", "on|off", "Whether the death loop goes back for the mage's own corpse after the respawn (default on; M4 2.2, D5): straight after the respawn and its vitals it teleports to where the mage died (the tuskers' den), opens its corpse, takes everything one pick-up at a time, closes it and teleports back to Holtburg before the re-gear, so the re-gear spawns only what the death destroyed. It is skipped, named in the log and reported as corpse_looted=skipped, when the respawn was not at the lifestone, no corpse was remembered, the corpse is older than ACE's rot floor of 3600 s, or the health share is under --death-recover-min-health; it aborts, named as trip_abort=<reason>, when the health falls under 40%, the trip takes over 90 s, the corpse is not there within 15 s of the arrival or ACE refuses the open. A death on the trip fails the leg. off is M3's run exactly (the corpse is left, the re-gear spawns the gear). The line reports corpse_looted=, items_recovered=, trip_s= and trip_abort= (report-only): corpse_looted=yes when every entry of the opened corpse came back, partial when some did (an abort, a refusal or a timeout cut it short; items_recovered counts the pick-up in flight at the abort once it settles), no when none did, skipped when no trip was made. A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-recover-min-health", "PCT", "The least health share, in percent of the maximum, the mage must have for the corpse trip to start (0 to 100, default 60; the respawn leaves it at 75). Under it the trip is skipped and named in the log (corpse_looted=skipped). A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-decoys", "on|off", "Whether the death loop's kit carries the decoys (default on; M4 3.1, D20): eight ordinary, light, expensive items (a Massive Mana Charge, an Intricate Carving Tool, a Handle Mold, a Tusker Island Shirt, a Skull Cap, a Virindi Scalpel, a Healing Chocolate Olthoi Cake, an Entrancing Adjanite Gem; 452 burden together), each the first of its death category and worth 8,000 or more, which the gear stage spawns with the server mod's item verb beside the rest of the kit. ACE drops the highest-valued items at a death (level 126: six to eight, Player_Death.cs and DeathItem.cs), so the decoys drop instead of the wand, the Olthoi Helm, the Platemail Gauntlets, the Sollerets and the spell components the loops need; bonded gear never drops. The gear stage logs the check over the live inventory (decoy check: N items above the wand ...). off is M3's kit exactly: no decoy is spawned or counted. A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-rebuff", "on|off", "Whether the death loop runs the buff cycle after the respawn (default on; M4 3.1, D20): the death purged every enchantment, so the full cycle (the fight scenario's buff stage, BuffCycle) runs at Holtburg after the respawn and the regear, before the fight. The line reports rebuffed=yes when the stage ended with every profile line up, no when it failed or ended with a line down, skipped when the stage is off (report-only). A death during it fails the leg, naming the rebuff stage. A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-fight", "on|off", "Whether the death loop fights at the Black Spawn Den after the respawn, the regear and the rebuff (default on; M4 3.1, D20): it goes back to the den, enters the magic combat mode and kills --death-fight-kills tuskers within --death-fight-seconds (the fight scenario's place and mode stages and its kill loop), and only then goes for its corpse, so the tuskers are dead when the trip arrives. off is M4 2.2's order exactly (the trip straight after the respawn's vitals, the regear after it). The line reports den_kills= (report-only). A death during the fight fails the leg, naming the fight stage; the death loop's own measures (died, vitae, vitals_pct, hits_taken and the rest) stay as the respawn's vitals wait left them. A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-fight-kills", "N", "The kills that end the death loop's fight (1 to 1000, default 4). A bad value fails the headless run and the game's bsd-death leg."),
        new("--death-fight-seconds", "S", "The most session-clock seconds the death loop's fight may take, from its first cast (above 0, default 180); past it the leg fails loudly with the fight's counts. A bad value fails the headless run and the game's bsd-death leg."),
    ], OptionScenes.Main | OptionScenes.Headless);
}
